from pathlib import Path
import json,html,zipfile,hashlib,shutil
ROOT=Path(__file__).resolve().parents[1];OUT=ROOT/'remix20';works=json.loads((OUT/'manifest.json').read_text()); esc=html.escape
base='https://github.com/wentaopeng714-cmd/openprocessing-loopit-20/releases/download/v6.0.0/'
CSS='''*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:var(--bg);color:var(--fg);font-family:Arial,sans-serif}canvas{position:fixed;inset:0;display:block;width:100%!important;height:100%!important;touch-action:none}#ui{position:fixed;inset:0;z-index:2;pointer-events:none;padding:calc(24px + env(safe-area-inset-top)) 24px calc(20px + env(safe-area-inset-bottom));display:flex;flex-direction:column;justify-content:space-between}header{max-width:330px;align-self:flex-start}small{font-size:10px;letter-spacing:.18em;text-transform:uppercase;opacity:.65}h1{font-size:29px;font-weight:400;letter-spacing:-.04em;line-height:1;margin:8px 0}p{font-size:12px;line-height:1.5;max-width:285px;margin:10px 0;opacity:.8}.tools{display:flex;gap:8px;flex-wrap:wrap;max-width:460px;pointer-events:auto;align-items:center}button,input{font:inherit;color:inherit}button{border:1px solid color-mix(in srgb,var(--fg) 25%,transparent);background:color-mix(in srgb,var(--bg) 92%,transparent);border-radius:5px;min-height:44px;padding:11px 14px;cursor:pointer;font-size:12px;backdrop-filter:blur(12px)}button:active,button[aria-pressed=true]{background:var(--fg);color:var(--bg)}button:focus-visible,input:focus-visible{outline:2px solid var(--accent);outline-offset:3px}label{display:flex;flex-direction:column;gap:8px;font-size:10px;letter-spacing:.08em;min-width:130px;background:color-mix(in srgb,var(--bg) 90%,transparent);padding:10px 12px;border-radius:5px}input[type=range]{accent-color:var(--accent);width:140px;height:24px;margin:0}output{float:right;opacity:.65}.utility{position:absolute;right:20px;top:calc(20px + env(safe-area-inset-top));pointer-events:auto;display:flex;gap:5px}.utility button{font-size:10px;min-height:36px;padding:8px}.quiet header,.quiet .tools{opacity:0;pointer-events:none}.quiet .utility button[data-action=pause]{display:none}.word input{background:transparent;border:0;border-bottom:1px solid currentColor;padding:6px 0;width:160px;font-family:Georgia;font-size:20px}.rail .tools{align-self:flex-end;flex-direction:column;align-items:stretch}.rail label input{width:110px}.editorial h1{font-family:Georgia;font-size:48px;max-width:230px}.editorial .tools{border-top:1px solid currentColor;padding-top:14px}.float .tools{align-self:center;justify-content:center;border-radius:20px;background:color-mix(in srgb,var(--bg) 75%,transparent);padding:10px}.split header{margin-top:40px}.split h1{font-size:43px;max-width:240px;text-transform:uppercase;line-height:.9}.split .tools{width:100%;justify-content:space-between}.bottom header{margin-top:auto;margin-bottom:20px}.bottom .tools button{border-radius:22px}.card .tools{max-width:240px;align-self:flex-end;padding:12px;background:var(--bg);border:1px solid var(--fg)}.corner header{align-self:flex-end;text-align:right;margin-top:42px}.corner .tools{max-width:230px}.round button{border-radius:50%;width:80px;height:80px;white-space:normal}.round .tools{justify-content:center;align-self:center}.round label{background:transparent}.caption header{margin-top:auto;margin-bottom:14px}.caption h1{font-family:Georgia;font-style:italic;font-size:43px}.caption .tools{max-width:100%;border-top:1px solid var(--fg);padding-top:10px}.side header{transform:rotate(-3deg);margin-top:30px}.side h1{font-size:38px}.side .tools{align-self:flex-end;max-width:220px}.stamp header{border:2px solid currentColor;padding:15px;transform:rotate(-3deg);margin-top:45px}.stamp .tools{align-self:center;justify-content:center}.topbar header{margin-top:40px}.topbar .tools{position:absolute;top:150px;left:24px;max-width:200px}.pill button{border-radius:50px}.pill h1{font-family:Georgia;font-style:italic;font-size:40px;max-width:230px}.notebook header{border-left:3px solid var(--accent);padding-left:12px}.notebook .tools{flex-direction:column;align-items:flex-start;max-width:190px}.notebook label{flex-direction:column;width:170px}.museum header{margin-top:40px;border-bottom:1px solid currentColor;padding-bottom:10px}.museum h1{font-family:Georgia;letter-spacing:0;font-size:35px}.museum .tools{justify-content:center;align-self:center}.route header{margin-top:auto;margin-bottom:16px}.route .tools{max-width:100%;border-top:1px dashed currentColor;padding-top:12px}.tilebar header{padding:15px;background:var(--bg);border:1px solid currentColor;margin-top:40px}.tilebar .tools{align-self:center}.type h1{font-size:40px;font-family:Georgia;max-width:170px}.type .tools{max-width:100%;align-items:end}.print header{margin-top:40px;border-top:3px solid currentColor}.print h1{text-transform:uppercase;font-size:30px;max-width:210px;letter-spacing:.02em}.print .tools{max-width:260px}.portrait header{align-self:center;text-align:center;margin-top:40px}.portrait h1{font-family:Georgia;font-size:35px;max-width:270px}.portrait .tools{align-self:center;justify-content:center;max-width:360px}#error{position:fixed;z-index:10;bottom:10px;left:10px;right:10px;display:none;background:#8e2828;color:white;padding:15px;font-size:12px}@media(max-width:420px){#ui{padding-left:18px;padding-right:18px}.utility{right:15px}header{max-width:260px}h1{font-size:27px}.tools{gap:6px}.tools button{padding:10px 11px}.topbar .tools{top:170px;left:18px}.rail .tools{max-width:155px}.caption h1{font-size:38px}.round button{width:72px;height:72px}.word input{width:140px}}'''
(OUT/'ui.css').write_text(CSS)
for w in works:
 folder=OUT/w['slug'];bg,fg,accent=w['theme'].split('|')
 buttons=''.join(f'<button data-action="{a}">{esc(label)}</button>' for a,label in w['buttons'])
 ranges=''.join(f'<label>{esc(label)}<output>{value}</output><input aria-label="{esc(label)}" type="range" data-action="{a}" min="{minv}" max="{maxv}" value="{value}" step="{step}"></label>' for a,label,minv,maxv,value,step in w['ranges'])
 markup=f'<main id="ui"><header><small>TOUCH STUDY {w["slug"][:2]} / 20</small><h1>{esc(w["title"])}</h1><p>{esc(w["changes"])}</p></header><div class="tools">{w["extra"]}{buttons}{ranges}</div><nav class="utility" aria-label="Display controls"><button data-action="pause">Pause</button><button data-action="quiet">Hide UI</button></nav></main><div id="error" role="alert"></div>'
 p5=(ROOT/'vendor'/('p5-1.3.1.min.js' if w['id']==1200087 else 'p5.min.js')).read_text()
 source=(folder/'sketch.js').read_text()
 document=f'<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="theme-color" content="{bg}"><title>{esc(w["title"])}</title><style>:root{{--bg:{bg};--fg:{fg};--accent:{accent}}}{CSS}</style></head><body class="{w["layout"]}">{markup}<!-- Adapted from https://openprocessing.org/sketch/{w["id"]}. Original credits and license: source.json in the companion ZIP. -->'
 document+='<script>'+p5.replace('</script','<\\/script')+'</script><script>'+source.replace('</script','<\\/script')+'</script>'
 document+='''<script>window.addEventListener('error',e=>{const n=document.getElementById('error');n.style.display='block';n.textContent='This artwork could not start: '+e.message;});</script></body></html>'''
 (folder/'index.html').write_text(document)
 (OUT/(w['slug']+'.html')).write_text(document)
 licence=f'''{w['title']} — OpenProcessing source adaptation\n\nOriginal: {w['original']}\nAuthor: {w['author']}\nSource: https://openprocessing.org/sketch/{w['id']}\nSource license captured: {w['license']}\nOriginal notices remain in the code. Source file URLs and SHA256 hashes are in source.json.\nAdaptation: {w['changes']}\nRetained visual algorithm: {w['algorithm']}\n\np5.js: LGPL-2.1; see P5-LICENSE.txt.\nChanges made October 2026. No claim of ownership over original code or assets.\n'''
 if w['license']=='by-nc-sa':licence+='\nNONCOMMERCIAL: This work retains CC BY-NC-SA. Commercial redistribution requires permission from its rights holders.\n'
 if w['license']=='unverified':licence+='\nOriginal-source license could not be verified due OpenProcessing API rate limiting. Do not redistribute publicly until the source license is confirmed. This package is a private working draft.\n'
 if w['id']==1200087:licence+='\nRay character rig and meshes: CGTarian Online School, as credited in Jason Labbe’s original sketch.\n'
 (folder/'CREDITS.txt').write_text(licence)
 with zipfile.ZipFile(OUT/(w['slug']+'.zip'),'w',zipfile.ZIP_DEFLATED) as z:
  z.write(folder/'index.html','index.html');z.write(folder/'sketch.js','adapted-sketch.js');z.write(folder/'adaptation.diff','adaptation.diff');z.write(folder/'source.json','source.json');z.write(folder/'CREDITS.txt','CREDITS.txt');z.write(ROOT/'vendor/P5-LICENSE.txt','P5-LICENSE.txt')
  for p in (ROOT/'research/op-new-20'/str(w['id'])).iterdir():
   if p.is_file():z.write(p,'original/'+p.name)
print('Packaged 20 standalone HTML files and 20 ZIPs')
